mapper.select:
select
wrdm.*
from wms_return_detail_manufactured wrdm
join wms_return_manufactured wrd on wrdm.return_manufactured_id = wrd.id and wrd.bool_delete_enum = 0 and wrd.review_status = 2
where wrdm.bool_delete_enum = 0

    and wrdm.basic_class & #{basicClass} > 0


    and wrdm.project_id = #{projectId}


    
        and wrd.application_time > #{applicationTime[0]}
    
    
        and wrd.application_time < #{applicationTime[1]}
    


    
        and wrd.review_pass_time >= #{reviewPassTime[0]}
    
    
        and wrd.review_pass_time <= #{reviewPassTime[1]}
    


    and wrd.serial_number like CONCAT('%', #{serialNumber},'%')


    and wrdm.specification like concat('%',#{specification},'%')
